@using sv_c302920b2913462592fd1fc96e5bb956.Services

<div class="message-area">
    @if (ActiveChannel is not null)
    {
        <div class="message-area-header">
            <h4># @ActiveChannel.Name</h4>
            <p class="text-muted mb-0">@ActiveChannel.Description</p>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="text-center p-2">
                    <span class="spinner-border spinner-border-sm"></span> Loading...
                </div>
            }
            @foreach (var message in Messages)
            {
                <MessageBubble Message="message"
                               ThreadReplyCount="GetThreadReplyCount(message.Id)"
                               OnOpenThread="OnOpenThread"
                               OnReact="OnReact" />
            }
        </div>

        <div class="message-input-area">
            <textarea class="form-control" placeholder="Type a message..."
                      @bind="newMessageText" @bind:event="oninput"
                      @onkeydown="HandleKeyDown" rows="2"></textarea>
            <button class="btn btn-primary mt-2" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageText)">
                Send
            </button>
        </div>
    }
    else
    {
        <div class="d-flex align-items-center justify-content-center h-100 text-muted">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = new();
    [Parameter] public Channel? ActiveChannel { get; set; }
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private string newMessageText = string.Empty;

    private int GetThreadReplyCount(int messageId)
    {
        var summary = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);
        return summary?.ReplyCount ?? 0;
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top triggers load more (handled via JS interop in production;
        // here we provide a simplified approach)
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;
        var text = newMessageText;
        newMessageText = string.Empty;
        await OnSendMessage.InvokeAsync(text);
    }
}

