.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background-color: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-title {
    padding: 16px;
    margin: 0;
    border-bottom: 1px solid #202225;
    font-weight: 600;
    color: #fff;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    border-radius: 4px;
    margin: 2px 8px;
}

::deep .channel-item:hover {
    background-color: #36393f;
}

::deep .channel-item.active {
    background-color: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
